/* Each 128-bit block of the bytes of `low` then `high` (when `both`;
 * zeros otherwise) from byte s on: AlignBytes, ShiftBytesRight with
 * s = n, and ShiftBytesLeft with s = -n. */
static inline zi_u8x16 zi_bytes_from_u8x16(zi_u8x16 high, zi_u8x16 low, int64_t s, int both)
{
#if ZI_LE
    union { zi_u8x16 v; unsigned char b[16]; } h_, l_, r_;
    h_.v = high;
    l_.v = low;
#else
    struct { unsigned char b[16]; } h_, l_, r_;
    zi_le_bytes_u8x16(high, h_.b);
    zi_le_bytes_u8x16(low, l_.b);
#endif
    memset(r_.b, 0, 16);
    for(int k = 0; k < 16; k += 16) {
        /* Output bytes [start, stop) of the block come from low, then from high. */
        int64_t start = s < 0 ? -s : 0, stop = s > 0 ? 16 - s : 16;
        if(start < stop) memcpy(r_.b + k + start, l_.b + k + start + s, (size_t)(stop - start));
        start = s < 16 ? 16 - s : 0;
        stop = s > 16 ? 32 - s : 16;
        if(both && start < stop) memcpy(r_.b + k + start, h_.b + k + start + s - 16, (size_t)(stop - start));
    }
#if ZI_LE
    return r_.v;
#else
    return zi_le_lanes_u8x16(r_.b);
#endif
}
